import JSON

"""
	gen( x, k, lambda, name )

Generate fixture data and write to file.

The logarithm of the CDF is evaluated in extended precision from the textbook formula `ln(1 - exp(-(x/lambda)^k))`, written with `expm1` so that it stays exact when `(x/lambda)^k` is far below the working precision, as `(x/lambda)^k` underflows in double precision for small `x`.

# Arguments

* `x`: input value
* `k`: shape parameter
* `lambda`: scale parameter
* `name::AbstractString`: output filename

# Examples

``` julia
julia> x = rand( 1000 ) .* 20.0;
julia> lambda = rand( 1000 ) .* 20.0;
julia> k = ( rand( 1000 ) .* 10.0 ) .+ 10.0;
julia> gen( x, k, lambda, "data.json" );
```
"""
function gen( x, k, lambda, name )
	z = setprecision( BigFloat, 2048 ) do
		Float64.( log.( .-expm1.( .-( ( BigFloat.( x ) ./ BigFloat.( lambda ) ) .^ BigFloat.( k ) ) ) ) )
	end

	# Store data to be written to file as a collection:
	data = Dict([
		("x", x),
		("lambda", lambda),
		("k", k),
		("expected", z)
	]);

	# Based on the script directory, create an output filepath:
	filepath = joinpath( dir, name );

	# Write the data to the output filepath as JSON:
	outfile = open( filepath, "w" );
	write( outfile, JSON.json(data) );
	write( outfile, "\n" );
	close( outfile );
end

# Get the filename:
file = @__FILE__;

# Extract the directory in which this file resides:
dir = dirname( file );

# Large scale parameter:
x = rand( 1000 ) .* 5.0;
lambda = ( rand( 1000 ) .* 5.0 ) .+ 5.0;
k = rand( 1000 ) .* 5.0;
gen( x, k, lambda, "large_scale.json" );

# Large shape parameter:
x = rand( 1000 ) .* 5.0;
lambda = rand( 1000 ) .* 5.0;
k = ( rand( 1000 ) .* 5.0 ) .+ 5.0;
gen( x, k, lambda, "large_shape.json" );

# Both large:
x = rand( 1000 ) .* 5.0;
lambda = ( rand( 1000 ) .* 5.0 ) .+ 10.0;
k = ( rand( 1000 ) .* 5.0 ) .+ 10.0;
gen( x, k, lambda, "both_large.json" );

# Small `x`:
x = exp10.( range( -323.0, stop = -2.0, length = 1000 ) );
lambda = ( rand( 1000 ) .* 5.0 ) .+ 0.5;
k = ( rand( 1000 ) .* 5.0 ) .+ 0.5;
gen( x, k, lambda, "small_x.json" );
